/**
 * The simple contacts (model contacts@1): the heading, a description and the contacts as a list on a card
 * surface, each with an icon picture (a disc), the name, a line and an action. Axes: layout (cards: columns, the
 * copy centred by the align setting, rows: the icon beside the copy), cols (2, 3 columns).
 */
import { type ReactNode } from "react";
import { Block, Container, LinkButton, List, ListItem, Stack, Text, Title } from "../compose";
import { MediaFrame } from "../components/media-frame";
import { cn, urlOf } from "../utils";
import type { ContactItem } from "./contacts-simple.types";

export type ContactsSimpleProps = {
  id: string;
  title: string;
  description?: string;
  items: ContactItem[];
  level?: 1 | 2 | 3;
  padding?: "compact" | "standard" | "spacious";
  align?: "start" | "center" | "end";
  layout?: "cards" | "rows";
  cols?: "3" | "2";
  landmarkLabel?: string;
};

export function ContactsSimple({
  id,
  title,
  description = "",
  items,
  level = 2,
  padding = "standard",
  align = "center",
  layout = "cards",
  cols = "3",
  landmarkLabel,
}: ContactsSimpleProps) {
  const titleId = id + "-title";
  const column =
    (align as string) === "center" ? "center"
    : (align as string) === "end" ? "end"
    : "start";
  const textAlign =
    (align as string) === "center" ? "text-center"
    : (align as string) === "end" ? "text-end"
    : "text-start";
  const itemsAlign =
    (align as string) === "center" ? "items-center"
    : (align as string) === "end" ? "items-end"
    : "items-start";
  const selfAlign =
    (align as string) === "center" ? "self-center"
    : (align as string) === "end" ? "self-end"
    : "";
  const grid = ((cols as string) === "2") ? "md:grid-cols-2" : "md:grid-cols-3";
  const item =
    (layout as string) === "rows" ? "flex flex-row items-start gap-4"
    : (align as string) === "center" ? "flex flex-col items-center gap-4"
    : (align as string) === "end" ? "flex flex-col items-end gap-4"
    : "flex flex-col items-start gap-4";
  const copyAlign =
    (layout as string) === "rows" ? "start"
    : (align as string) === "center" ? "center"
    : (align as string) === "end" ? "end"
    : "start";
  const copyText =
    (layout as string) === "rows" ? "text-start"
    : (align as string) === "center" ? "text-center"
    : (align as string) === "end" ? "text-end"
    : "text-start";
  return (
    <Block
      tag="section"
      className={
        (padding as string) === "compact" ? "py-8 lg:py-16"
        : (padding as string) === "spacious" ? "py-24 lg:py-40"
        : "py-16 lg:py-32"
      }
      aria-labelledby={(landmarkLabel ? undefined : titleId)}
      aria-label={landmarkLabel}
      data-slot="contacts-simple"
    >
      <Container className="mx-auto w-full max-w-6xl px-4">
        <Stack gap="12" align="stretch">
          <Stack gap="4" align={column} className={cn("max-w-2xl", selfAlign)}>
            <Title as={level} size="3xl" weight="bold" className={cn("tracking-tight", textAlign)} id={titleId}>
              {title}
            </Title>
            {description ? (
              <Text size="base" className={cn("text-muted-foreground", textAlign)}>
                {description}
              </Text>
            ) : null}
          </Stack>
          <List tag="ul" className={cn("m-0 w-full list-none p-0", cn("grid grid-cols-1 gap-6", grid))}>
            {(items ?? []).map((c) => (
              <ListItem key={c.id}
                className={cn("rounded bg-card p-6 text-card-foreground border border-border", item)}
                data-slot="contact"
              >
                <MediaFrame alt={c.title} src={c.image} ratio="1/1" className="size-12 shrink-0 rounded-full" />
                <Stack gap="4" align={copyAlign}>
                  <Stack gap="2" align={copyAlign}>
                    <Title as={(level + 1)} size="lg" weight="semibold" className={copyText}>
                      {c.title}
                    </Title>
                    {c.description ? (
                      <Text size="sm" className={cn("text-muted-foreground", copyText)}>
                        {c.description}
                      </Text>
                    ) : null}
                  </Stack>
                  {(c.actionLabel && c.actionHref) ? (
                    <LinkButton variant="default" size="sm" href={urlOf(c.actionHref)}>
                      {c.actionLabel}
                    </LinkButton>
                  ) : null}
                </Stack>
              </ListItem>
            ))}
          </List>
        </Stack>
      </Container>
    </Block>
  );
}

